sys_script_client.script:
function onSubmit() {

    var taskType = g_form.getValue('trade_task_type');
    var swiftVal = g_form.getValue('swift_linking_reference_id_ref');
//	alert(swiftVal);

    if (taskType == 'Maker' && swiftVal != '') {

        var ga = new GlideAjax('HSBCTradeTaskUtils');
        ga.addParam('sysparm_name', 'getTradeSwift');
		ga.addParam('sysparm_taskSysID', g_form.getUniqueValue());
        ga.addParam('sysparm_tradeSysId', swiftVal);


        ga.getXMLAnswer(function(response) {
            if (response != '') {
		//		alert(response);
          //      g_form.setValue('swift_linking_reference_id', response);
           //     g_form.setValue('swift_linking_reference', swiftVal);

            } else {
                return false;
            }
        });
    }

}
